    #[tokio::test]
    async fn send_runtime_command_across_threads() -> Result<(), SipError> {
        let (cmd_tx, mut cmd_rx) = new_command_channel();
        let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();

        // Send from a spawned task
